let DATA=DEFAULT_DATA.slice();
let viewRange='all';
let scaleMode='detail';
let zoomBounds=null;
let manualDataLoaded=false;
const TZ='Asia/Ho_Chi_Minh';
const $=id=>document.getElementById(id);
const fmtDate=new Intl.DateTimeFormat('vi-VN',{timeZone:TZ,day:'2-digit',month:'2-digit',year:'numeric'});
const fmtTime=new Intl.DateTimeFormat('vi-VN',{timeZone:TZ,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const fmtTimeShort=new Intl.DateTimeFormat('vi-VN',{timeZone:TZ,hour:'2-digit',minute:'2-digit',hour12:false});
function statusName(s){return s===2?'HIGH':s===1?'LOW':'NORMAL'}
function statusClass(s){return s===2?'status-high':s===1?'status-low':'status-normal'}
function statusColor(s){return s===2?'#dc2626':s===1?'#f59e0b':'#16a34a'}
function median(a){if(!a.length)return 0;const x=a.slice().sort((p,q)=>p-q),m=Math.floor(x.length/2);return x.length%2?x[m]:(x[m-1]+x[m])/2}
function timingStats(v){
  if(v.length<2)return {cadence:0,gapThreshold:15,gaps:0,sessions:v.length?1:0,recordingMs:0,minRegular:0,maxRegular:0};
  const diffs=[];for(let i=1;i<v.length;i++){const d=(v[i][0]-v[i-1][0])/1000;if(d>0)diffs.push(d)}
  const cadence=median(diffs.filter(d=>d<300))||median(diffs)||0;
  const gapThreshold=Math.max(15,cadence*3);
  let gaps=0,sessions=1,recordingMs=0;const regular=[];
  for(let i=1;i<v.length;i++){
    const d=(v[i][0]-v[i-1][0])/1000;
    if(d>0&&d<=gapThreshold){recordingMs+=d*1000;regular.push(d)}else if(d>gapThreshold){gaps++;sessions++}
  }
  return {cadence,gapThreshold,gaps,sessions,recordingMs,minRegular:regular.length?Math.min(...regular):0,maxRegular:regular.length?Math.max(...regular):0};
}
function getViewData(){
  if(viewRange==='all') return DATA;
  const end=DATA[DATA.length-1][0], start=end-Number(viewRange)*60*1000;
  return DATA.filter(r=>r[0]>=start&&r[0]<=end);
}
function getViewBounds(){
  const end=DATA[DATA.length-1][0];
  if(viewRange==='all')return [DATA[0][0],end];
  return [end-Number(viewRange)*60*1000,end];
}
function getChartBounds(){return zoomBounds?zoomBounds.slice():getViewBounds()}
function clampZoomBounds(a,b){
  const [base0,base1]=getViewBounds();
  const baseSpan=Math.max(1,base1-base0);
  const cadence=timingStats(getViewData()).cadence||5;
  const minSpan=Math.min(baseSpan,Math.max(30000,cadence*6*1000));
  let span=Math.max(minSpan,Math.min(baseSpan,b-a));
  let t0=a,t1=a+span;
  if(t0<base0){t0=base0;t1=base0+span}
  if(t1>base1){t1=base1;t0=base1-span}
  return [t0,t1];
}
function updateZoomUI(){
  const active=!!zoomBounds;
  $('resetZoomBtn').classList.toggle('visible',active);
}
function setZoomAround(center,factor){
  const cur=getChartBounds(),span=cur[1]-cur[0];
  const [base0,base1]=getViewBounds(),baseSpan=base1-base0;
  const cadence=timingStats(getViewData()).cadence||5;
  const minSpan=Math.min(baseSpan,Math.max(30000,cadence*6*1000));
  let newSpan=Math.max(minSpan,Math.min(baseSpan,span*factor));
  if(newSpan>=baseSpan*.999){zoomBounds=null;updateZoomUI();drawTrend(getViewData());return}
  const ratio=Math.max(0,Math.min(1,(center-cur[0])/(span||1)));
  zoomBounds=clampZoomBounds(center-ratio*newSpan,center+(1-ratio)*newSpan);
  updateZoomUI();drawTrend(getViewData());
}
function panZoom(deltaMs,startBounds){
  if(!zoomBounds&&!startBounds)return;
  const b=startBounds||zoomBounds;zoomBounds=clampZoomBounds(b[0]+deltaMs,b[1]+deltaMs);updateZoomUI();drawTrend(getViewData());
}
function resetChartZoom(){zoomBounds=null;updateZoomUI();drawTrend(getViewData())}
function durationText(ms){
  let s=Math.max(0,Math.round(ms/1000));const h=Math.floor(s/3600);s%=3600;const m=Math.floor(s/60);const sec=s%60;
  if(h)return `${h} giờ ${m} phút ${sec} giây`;
  return `${m} phút ${sec} giây`;
}
function renderAll(){
  const v=getViewData();if(!v.length)return;
  const last=v[v.length-1],vals=v.map(r=>r[1]),tim=timingStats(v);
  $('kCurrent').textContent=last[1];$('kMin').textContent=Math.min(...vals);$('kMax').textContent=Math.max(...vals);$('kAvg').textContent=(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1);
  $('kCount').textContent=v.length.toLocaleString('vi-VN');
  $('kCadence').textContent=tim.cadence?`Chu kỳ lấy mẫu: ${tim.cadence.toFixed(1)} giây`:'—';
  $('kDuration').textContent=durationText(tim.recordingMs);
  $('kWindow').textContent=`${fmtTimeShort.format(new Date(v[0][0]))} → ${fmtTimeShort.format(new Date(last[0]))}`;
  $('kStatus').innerHTML=`<span class="status-pill ${statusClass(last[7])}">${statusName(last[7])}</span>`;
  $('tHigh').textContent=last[2];$('tLow').textContent=last[3];$('tHighOff').textContent=last[4];$('tLowOff').textContent=last[5];$('tHyst').textContent=last[6];
  const firstAll=DATA[0],lastAll=DATA[DATA.length-1];
  const dateLabel=fmtDate.format(new Date(firstAll[0]))===fmtDate.format(new Date(lastAll[0]))?fmtDate.format(new Date(lastAll[0])):`${fmtDate.format(new Date(firstAll[0]))} – ${fmtDate.format(new Date(lastAll[0]))}`;
  $('datasetBadge').textContent=`${dateLabel} · ${DATA.length.toLocaleString('vi-VN')} mẫu`;
  $('footerRange').textContent=`${fmtDate.format(new Date(v[0][0]))} ${fmtTime.format(new Date(v[0][0]))} → ${fmtDate.format(new Date(last[0]))} ${fmtTime.format(new Date(last[0]))}`;
  $('rangeInfo').textContent=viewRange==='all'?`${v.length.toLocaleString('vi-VN')} mẫu`:`${viewRange} phút gần nhất · ${v.length.toLocaleString('vi-VN')} mẫu`;
  renderTimeline(v);renderQuality(v);renderTable(v);drawTrend(v);
}
function renderTimeline(v){
  const c={0:0,1:0,2:0};v.forEach(r=>c[r[7]]=(c[r[7]]||0)+1);const n=v.length;
  $('alarmSummary').innerHTML=[0,1,2].map(s=>`<div class="status-row"><span class="left"><i class="status-dot" style="background:${statusColor(s)}"></i>${statusName(s)}</span><b>${(c[s]/n*100).toFixed(1)}%</b></div>`).join('');
  const el=$('timeline');el.innerHTML='';[0,1,2].forEach(s=>{if(c[s]){const d=document.createElement('div');d.style.width=(c[s]/n*100)+'%';d.style.background=statusColor(s);d.title=`${statusName(s)} · ${c[s].toLocaleString('vi-VN')} mẫu`;el.appendChild(d)}});
}
function renderQuality(v){
  const t=timingStats(v);const stable=v.every(r=>r[2]===v[0][2]&&r[3]===v[0][3]&&r[6]===v[0][6]);
  $('quality').innerHTML=`
    <div class="quality-item"><div class="qname">Chu kỳ</div><div class="qvalue">${t.cadence?t.cadence.toFixed(1)+' s':'—'}</div></div>
    <div class="quality-item"><div class="qname">Khoảng gián đoạn</div><div class="qvalue">${t.gaps}</div></div>
    <div class="quality-item"><div class="qname">Số phiên ghi</div><div class="qvalue">${t.sessions}</div></div>
    <div class="quality-item"><div class="qname">Ngưỡng cài đặt ổn định</div><div class="qvalue">${stable?'Có':'Không'}</div></div>`;
}
function renderTable(v){
  $('latestRows').innerHTML=v.slice(-12).reverse().map(r=>`<tr><td>${fmtDate.format(new Date(r[0]))} ${fmtTime.format(new Date(r[0]))}</td><td class="num"><b>${r[1]}</b></td><td class="num">${r[2]}</td><td class="num">${r[3]}</td><td class="num">${r[4]}</td><td class="num">${r[5]}</td><td class="num">${r[6]}</td><td><span class="status-pill ${statusClass(r[7])}">${statusName(r[7])}</span></td></tr>`).join('');
}

const canvas=$('trend'),tip=$('tooltip');let plotCache=null;
function drawTrend(v){
  const [t0,t1]=getChartBounds();
  let chartV=v.filter(r=>r[0]>=t0&&r[0]<=t1);if(!chartV.length)chartV=v;
  const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));
  const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;ctx.clearRect(0,0,W,H);
  const m={l:62,r:22,t:22,b:44},pw=W-m.l-m.r,ph=H-m.t-m.b;
  let yMin,yMax;const vals=chartV.map(r=>r[1]),lo=Math.min(...vals),hi=Math.max(...vals);
  if(scaleMode==='full'){yMin=0;yMax=600}else{const span=Math.max(16,hi-lo);const pad=Math.max(5,span*.35);yMin=Math.floor((lo-pad)/5)*5;yMax=Math.ceil((hi+pad)/5)*5;if(yMax<=yMin)yMax=yMin+20;}
  const x=t=>m.l+(t-t0)/(t1-t0||1)*pw,y=val=>m.t+(yMax-val)/(yMax-yMin)*ph;
  ctx.font='12px Arial';ctx.fillStyle='#667085';ctx.strokeStyle='#e7edf4';ctx.lineWidth=1;
  for(let i=0;i<=5;i++){const val=yMin+(yMax-yMin)*(5-i)/5,yy=m.t+ph*i/5;ctx.beginPath();ctx.moveTo(m.l,yy);ctx.lineTo(W-m.r,yy);ctx.stroke();ctx.fillText(Math.round(val)+' mV',8,yy+4)}
  for(let i=0;i<=6;i++){const xx=m.l+pw*i/6;ctx.beginPath();ctx.moveTo(xx,m.t);ctx.lineTo(xx,H-m.b);ctx.stroke();const tt=t0+(t1-t0)*i/6,s=fmtTimeShort.format(new Date(tt));ctx.fillText(s,xx-15,H-16)}
  function threshold(val,color,label){if(val<yMin||val>yMax)return;const yy=y(val);ctx.save();ctx.strokeStyle=color;ctx.setLineDash([7,6]);ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(m.l,yy);ctx.lineTo(W-m.r,yy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;ctx.font='bold 11px Arial';ctx.fillText(label+' '+val,m.l+7,yy-7);ctx.restore()}
  threshold(chartV[chartV.length-1][2],'#dc2626','HIGH');threshold(chartV[chartV.length-1][3],'#f59e0b','LOW');
  const tim=timingStats(chartV);ctx.strokeStyle='#2563eb';ctx.lineWidth=2;ctx.beginPath();let started=false;
  chartV.forEach((r,i)=>{const xx=x(r[0]),yy=y(r[1]);const gap=i>0?(r[0]-chartV[i-1][0])/1000:0;if(!started||gap>tim.gapThreshold){ctx.moveTo(xx,yy);started=true}else ctx.lineTo(xx,yy)});ctx.stroke();
  plotCache={v:chartV,m,pw,ph,W,H,t0,t1,yMin,yMax,x,y,cadence:tim.cadence,gapThreshold:tim.gapThreshold};
}
canvas.addEventListener('mousemove',e=>{
  if(!plotCache)return;const r=canvas.getBoundingClientRect(),mx=e.clientX-r.left,p=plotCache;if(mx<p.m.l||mx>p.W-p.m.r){tip.style.display='none';return}
  const target=p.t0+(mx-p.m.l)/p.pw*(p.t1-p.t0);let lo=0,hi=p.v.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(p.v[mid][0]<target)lo=mid+1;else hi=mid}let idx=Math.max(0,lo);if(idx>0&&Math.abs(p.v[idx-1][0]-target)<Math.abs(p.v[idx][0]-target))idx--;const q=p.v[idx];
  const maxNear=Math.max(20,(p.cadence||5)*4)*1000;if(Math.abs(q[0]-target)>maxNear){tip.style.display='none';drawTrend(getViewData());return}
  const xx=p.x(q[0]),yy=p.y(q[1]);drawTrend(getViewData());const ctx=canvas.getContext('2d');ctx.save();ctx.strokeStyle='#94a3b8';ctx.setLineDash([3,3]);ctx.beginPath();ctx.moveTo(xx,p.m.t);ctx.lineTo(xx,p.H-p.m.b);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#2563eb';ctx.beginPath();ctx.arc(xx,yy,4,0,Math.PI*2);ctx.fill();ctx.restore();
  tip.innerHTML=`<b>${fmtTime.format(new Date(q[0]))}</b><br>ORP: <b>${q[1]} mV</b><br>Trạng thái: <b>${statusName(q[7])}</b>`;tip.style.display='block';tip.style.left=Math.min(xx,p.W-155)+'px';tip.style.top=Math.max(48,Math.min(yy,p.H-42))+'px';
});
canvas.addEventListener('mouseleave',()=>{tip.style.display='none';drawTrend(getViewData())});
window.addEventListener('resize',()=>drawTrend(getViewData()));

